#[test]
fn routed_rust_workflow_contract_accepts_github_hosted_shape() {
    let workflow = r#"
jobs:
  route:
    name: Route Ripr Rust Small
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Plan the source route
        run: |
          route=github_hosted_rust
          echo "self_hosted_selection_attempted=false"
          echo "private_runner_secret_requested=false"
          echo "org_runner_query_attempted=false"
          echo "plan_version=1"
          echo "subject_sha=$SUBJECT_SHA"
          echo "pr_head_sha=$PR_HEAD_SHA"
  detect-docs-only:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - run: echo detect
  rust-github:
    name: Ripr Rust Small on GitHub Hosted
    runs-on: ubuntu-latest
    timeout-minutes: 90
    steps:
      - uses: actions/checkout@v6
        with:
          ref: ${{ needs.route.outputs.subject_sha }}
          persist-credentials: false
    if: always() && needs.route.result == 'success' &&
      needs.route.outputs.route == 'github_hosted_rust' &&
      needs.detect-docs-only.result == 'success' &&
      needs.detect-docs-only.outputs.docs_only != 'true'
    outputs:
      observed_subject_sha: ${{ steps.subject.outputs.observed_subject_sha }}
      observed_subject_tree: ${{ steps.subject.outputs.observed_subject_tree }}
    steps:
      - run: cargo xtask proof route --base "$BASE_SHA" --head "$HEAD_SHA" || true
  docs-gate:
    runs-on: ubuntu-latest
    timeout-minutes: 60
    steps:
      - run: cargo xtask precommit
  result:
    name: Ripr Rust Small Result
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - run: |
          cargo run --locked -p xtask -- ci-routed-rust-result             --planned-route "$planned"             --child-conclusion "$CHILD_CONCLUSION"             --receipt-state "$RECEIPT_STATE"             --planned-subject "$PLANNED_SUBJECT"             --observed-subject "$OBSERVED_SUBJECT"
"#;
    let settings = r#"
repository:
  name: ripr-swarm
branches:
  - name: main
    protection:
      required_status_checks:
        contexts:
          - Ripr Rust Small Result
"#;
    let lane = r#"
[[lane]]
id = "routed-rust-small"
workflow = ".github/workflows/routed-rust.yml"
jobs = ["Ripr Rust Small Result"]
"#;

    let violations = routed_rust_workflow_contract_violations(workflow, Some(settings), Some(lane));
    assert!(
        violations.is_empty(),
        "unexpected violations: {violations:?}"
    );
}

#[test]
fn routed_rust_workflow_contract_rejects_self_hosted_reintroduction() {
    // ripr#1446: self-hosted runner authority belongs to ripr-swarm. The source
    // contract must reject any attempt to bring it back, including a lane that is
    // merely declared and never selected.
    let workflow = r#"
jobs:
  route:
    name: Route Ripr Rust Small
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - name: Select runner
        env:
          GH_TOKEN: ${{ secrets.EM_RUNNER_READ_TOKEN || github.token }}
        run: |
          gh api --paginate orgs/EffortlessMetrics/actions/runners
          reason=runner_api_failed
  detect-docs-only:
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - run: echo detect
  rust-cx53:
    runs-on: self-hosted
    timeout-minutes: 90
    env:
      CARGO_HOME: /mnt/ci-scratch/cargo-home
    steps:
      - run: ci-disk-guard /mnt/ci-scratch 50
  result:
    name: Ripr Rust Small Result
    runs-on: ubuntu-latest
    timeout-minutes: 10
    steps:
      - run: echo done
"#;
    let settings = r#"
repository:
  name: ripr-swarm
branches:
  - name: main
    protection:
      required_status_checks:
        contexts:
          - Ripr Rust Small Result
          - Ripr Rust Small on CX53
"#;
    let lane = r#"
[[lane]]
id = "routed-rust-small"
workflow = ".github/workflows/routed-rust.yml"
jobs = ["Ripr Rust Small Result", "Ripr Rust Small on CX53"]
"#;

    let violations = routed_rust_workflow_contract_violations(workflow, Some(settings), Some(lane));

    for expected in [
        "actions/runners",
        "EM_RUNNER_READ_TOKEN",
        "runs-on: self-hosted",
        "cx53",
        "/mnt/ci-scratch",
        "ci-disk-guard",
        "runner_api_failed",
    ] {
        assert!(
            violations
                .iter()
                .any(|violation| violation.contains(expected)),
            "contract must reject `{expected}`; violations were {violations:?}"
        );
    }

    // The GitHub-hosted route requirements are absent, so those must be reported
    // as missing rather than passing vacuously.
    assert!(
        violations
            .iter()
            .any(|violation| violation.contains("route=github_hosted_rust")),
        "contract must require the github-hosted route: {violations:?}"
    );

    // Branch protection must not require a conditional implementation job.
    assert!(
        violations
            .iter()
            .any(|violation| violation.contains("Ripr Rust Small on CX53")),
        "contract must reject requiring a conditional implementation job: {violations:?}"
    );
}

#[test]
fn routed_rust_contract_catches_deadline_bypass_with_stray_occurrences() {
    // #2230 review: a global `timeout-minutes:` occurrence count passes even
    // when a named job lost its deadline but stray tokens (comments, other
    // jobs, duplicates) keep the total at eight. The per-job check must fire
    // on the job that lost its deadline.
    let workflow = r#"
name: Routed Rust Small
jobs:
  route:
    runs-on: ubuntu-latest
    timeout-minutes: 10
  detect-docs-only:
    runs-on: ubuntu-latest
    timeout-minutes: 10
  rust-cx43:
    runs-on: ubuntu-latest
    timeout-minutes: 60
    # timeout-minutes: 60 (stray occurrence in a comment)
  rust-cpx42:
    runs-on: ubuntu-latest
    timeout-minutes: 60
    timeout-minutes: 60
  rust-cx53:
    runs-on: ubuntu-latest
    timeout-minutes: 60
  rust-github:
    runs-on: ubuntu-latest
    timeout-minutes: 90
  docs-gate:
    runs-on: ubuntu-latest
    timeout-minutes: 20
  result:
    runs-on: ubuntu-latest
"#;
    let violations = routed_rust_workflow_contract_violations(workflow, None, None);
    assert!(
        violations.iter().any(|violation| violation
            .contains("job `result` must set an explicit `timeout-minutes` job deadline")),
        "missing per-job deadline must fire even with 8 stray occurrences: {violations:?}"
    );
    assert!(
        !violations
            .iter()
            .any(|violation| violation.contains("job `route` must set an explicit")),
        "a job that kept its deadline must not be flagged: {violations:?}"
    );
}

